// src/pages/ProductHome.jsx
import React from "react";
import { Link } from "react-router-dom";
import "./ProductHome.css"; // Make sure this CSS file exists and is styled
import Pc_components from "../Assets/pc.jpeg"
const products = {
  "PC Components": [
    {
      name: "Graphics Card",
      img: Pc_components,
    },
    {
        name: "Graphics Card",
        img: Pc_components,
    },
    {
        name: "Graphics Card",
        img: Pc_components,
    },
  ],
  "Laptop Components": [
    {
      name: "Laptop Battery",
      img: "https://cdn.pixabay.com/photo/2016/11/29/04/17/laptop-1867745_1280.jpg",
    },
    {
      name: "Laptop Charger",
      img: "https://cdn.pixabay.com/photo/2016/03/27/22/16/technology-1283624_1280.jpg",
    },
    {
      name: "Laptop SSD",
      img: "https://cdn.pixabay.com/photo/2015/01/08/18/24/laptop-593673_1280.jpg",
    },
  ],
  "Mobile Components": [
    {
      name: "Phone Display",
      img: "https://cdn.pixabay.com/photo/2014/09/23/21/23/smartphone-458856_1280.jpg",
    },
    {
      name: "Phone Battery",
      img: "https://cdn.pixabay.com/photo/2013/07/12/12/58/smartphone-146721_1280.png",
    },
    {
      name: "Phone Camera Module",
      img: "https://cdn.pixabay.com/photo/2015/07/17/22/43/student-849821_1280.jpg",
    },
  ],
  "Cloth Components": [
    {
      name: "T-Shirt",
      img: "https://cdn.pixabay.com/photo/2016/03/27/19/31/fashion-1283863_1280.jpg",
    },
    {
      name: "Jeans",
      img: "https://cdn.pixabay.com/photo/2015/09/02/12/45/fashion-918446_1280.jpg",
    },
    {
      name: "Hoodie",
      img: "https://cdn.pixabay.com/photo/2015/03/26/09/41/fashion-690546_1280.jpg",
    },
  ],
};

const ProductHome = () => {
  return (
    <div className="product-container">
      <h1 className="title">Explore Categories</h1>
      {Object.entries(products).map(([category, items]) => (
        <div key={category} className="category-section">
          <h2 className="category-title">{category}</h2>
          <div className="product-grid">
            {items.map((item, index) => (
              <Link
                key={index}
                to={`/product/${encodeURIComponent(category)}/${encodeURIComponent(item.name)}`}
                className="product-link"
              >
                <div className="product-card">
                  <img src={item.img} alt={item.name} className="product-image" />
                  <h3 className="product-name">{item.name}</h3>
                </div>
              </Link>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

export default ProductHome;
